INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`) VALUES
(2358,'ruRU','Рога Нез''ры','Верните рога Незры Арантиру в Приозерье.','Много лет назад рога Незры были похищены из поместья Черный Ворон. Я искал их по всем морям и континентам и только теперь выяснил, что они все время находились у этих ничтожных тварей.$B$BУбей всех орков Черной Горы, которые встретятся тебе на пути, забери у них рога Незры и возвращайся ко мне в Приозерье.$B$BОкажи мне эту услугу, и заслужишь благодарность всех Черных Воронов.',NULL),
(6221,'ruRU','Северные фурболги Мертвого Леса','Нафиэн просит вас убить 5 дозорного из племени Мертвого Леса, 5 мстителей и 5 шаманов из племени Мертвого Леса.','Прямо на юго-западе отсюда расположен лагерь фурболгов Мертвого Леса. В лагере царствует порча, и я хочу положить этому конец прежде, чем эти фурболги стали настоящей угрозой.$B$BПлемя Мервтого Леса злобное, но это все действие скверны, поразившей их разум. Они не враждебны от природы, но тут уж ничего не поделать. Мне невыносимо тяжело сражаться против собратьев.$B$BПрошу тебя, $N, делай, что должно, но не рассказывай мне подробностей – у меня и без того сердце разрывается.',NULL),
(6241,'ruRU','Боевые действия в деревне Зимней Спячки','Убейте 6 тотемистов, 6 дозорных и 6 землепроходцев из племени Зимней Спячки по просьбе Сальфы.','Клан Древобрюхов готов постоять за себя, $N. В то время как мы позволяем свободно ходить среди нас тем, кому мы доверяем, мы стараемся по возможности избегать общения с другими племенами фурболгов. $B$BПлемя Зимней Спячки в последнее время становится все более враждебным к нам. Они, похоже, впали в состояние ярости, всецело поглощенные собственным страхом и ненавистью ко всему, чего они не понимают. $B$BЕсли бы вы могли сократить их число, это бы нам здорово помогло, $N.',NULL),
(7361,'ruRU','Благосклонность клана Черного Копья','Вам поручили убивать в Альтеракской долине ночных эльфов.$B$BУбив ночного эльфа, вернитесь с его отрубленной головой к Нажьяку Проклятуну в крепость Северного Волка.','*Нажьяк ворчит.* $B$BПрежде чем появились ночные эльфы, были тролли. И именно от троллей пошли ночные эльфы. $B$BИх злобные вылазки против моего народа нельзя более терпеть. Олений Шлем хочет стереть нас с лица земли, чтобы не осталось и упоминания о тех, от кого ведут свой род он и его собратья. Не бывать этому! $B$BЗа каждого ночного эльфа, которого ты убьешь и обезглавишь, Надьяк будет одаривать тебя благосклонностью народа Черного Копья. Слава о твоих деяниях распространится по всему Калимдору и Восточным королевствам. Иди же и послужи Черному Копью!',NULL),
(7362,'ruRU','Союзник тауренов','Убивайте гномов в Альтеракской долине.$B$BУбив гнома, принесите Раваку Зловещему Тотему в крепость Северного Волка пучок волос гнома.','Мудрая Магата прислала меня в эту зону боевых действий, чтобы изучать другие расы. Точнее, мне поручено собрать образцы тканей гномов. Магату особенно интересует их живучесть. Ведь гномы – эти крошечные, жалкие создания, – проявляют удивительную устойчивость как к боевым ранениям, так и к обычным тяготам жизни.$B$BТебе повезло – мне как раз нужны помощники, чтобы выполнить поручение Магаты. Приноси мне пряди гномьих волос, и таурены будут считать тебя своим союзником.',NULL),
(7363,'ruRU','Человечья жизнь','Вам поручили убивать людей в Альтеракской долине.$B$BУбив человека, принесите командору Луи Филипсу (который бродит между линией фронта и крепостью Северного Волка) осколок человеской кости.$B$BОкончить человеческие страдания совсем несложно!','Люди так отвратительны!$B$B*Командир Филипс брезгливо кривится.*$B$BКонечно, сейчас я состою на службе у клана Северного Волка, и все же я по-прежнему остаюсь слугой Сильваны.$B$BИ в свободное от службы время я подрабатываю, помогая Темным аптекарям Подгорода.$B$BМне поручено собирать осколки человеческих костей, которые будут использованы, чтобы исцелять людей от их жалкого состояния.$B$BЯ также могу давать аналогичное поручение своим подчиненным.$B$BИщите их. Убивайте их. И приносите мне осколки их костей!',NULL),
(7364,'ruRU','Награда Гномрегана','Убивайте тауренов в Альтеракской долине.$B$BУбив таурена, вернитесь к Дирку Надувалло в Дун Болдар с копытом таурена.','Сам главный механик прислал меня на это поле брани, чтобы защитить наших собратьев! До нас дошли вести, что таурены нарочно выискивают и убивают гномов! А самое ужасное, что они срезают с трупов павших их роскошные волосы! Этому необходимо положить конец. Мы обязаны отомстить!$B$BМы лишим их копыт, $c! Принеси мне их копыта! Докажи, что ты – союзник гномов!',NULL),
(7365,'ruRU','Реквием Оленьего Шлема','Ваше задание – убивать в Альтеракской долине троллей.$B$BУбейте тролля и возвращайтесь к Атраманису в Дун Болдар с амулетом тролля из клана Черного Копья.','Олений Шлем отдал приказ: во время сражений всех троллей необходимо истребить. Они должны ответить за свое наглое заявление, что ночные эльфы ведут свой род от троллей.$B$BУничтожь троллей и принеси мне их амулеты. Повторяю: мне нужны их амулеты.',NULL),
(7366,'ruRU','Милосердие архиепископа','Ваше задание – убивать в Альтеракской долине Отрекшихся.$B$BУбейте Отрекшегося и возвращайтесь к Карлу Филипсу (он ходит между лесопилкой и рудником) с сердцем Отрекшегося.','Доброта архиепископа сравнима только с его мудростью. Надо иметь невероятно чуткую душу, чтобы относиться к подобной швали с милосердием...$B$B*Командир Филипс в недоумении пожимает плечами.*$B$BОн слишком добр... Просто слишком.$B$BАрхиепископ просил нас, чтобы мы имели сострадание к нежити и даровали им быструю и верную смерть. Чтобы проявить подобное великодушие, мы должны раздобыть их черные, пораженные болезнью сердца.$B$BПринеси мне сердца Отрекшихся, чтобы мы могли сжечь их с надлежащими церемониями в Соборе Света. Поспеши, $N!',NULL),
(7381,'ruRU','Возвращение Коррака','В случае, если Коррак Кровопуск возвратится на Поле брани, найдите его и уничтожьте.$B$BПринесите череп Коррака воеводе Лаггронду в предгорья Хилсбрада.','Коррак мертв, но надолго ли? О магии троллей ходит грозная слава. Я не удивлюсь, если их мертвый вождь снова восстанет, чтобы править своим племенем.$B$BТы знаешь, что делать, если это случится.$B$B*Воевода Лаггронд проводит ребром ладони по горлу.*$B$BНо на этот раз принеси его череп. И гляди в оба, солдат!$B$B$GСвободен:Свободна;!',NULL),
(7382,'ruRU','Коррак Бессмертный','В случае, если Коррак Кровопуск возвратится на Поле брани, найдите его и уничтожьте.$B$BПринесите череп Коррака лейтенанту Мурпу в предгорья Хилсбрада.','Что-то здесь не так... Кто-нибудь догадался сжечь тело Коррака? Эти синекожие язычники ни перед чем не остановятся, чтобы возродить своего вождя.$B$BСмотри в оба, $N. Не удивляйся, если снова увидишь Коррака в живых. Убей его снова, но на этот раз обязательно сожги тело.$B$BЧтобы уж все проделать наверняка, отрежь ему голову и принеси череп мне, а все остальное пусть горит синим пламенем.',NULL),
(7401,'ruRU','Разыскиваются: ДВОРФЫ!','Ваша задача – убивать дворфов в Альтеракской долине.$B$BУбейте дворфа и вырвите ему хребет. Отнесите хребет дворфа сержанту Язре Кровавый Рык в крепость Северного Волка.','Согласно приказу сержанта Язры Кровавый Рык, все дворфы на поле сражения подлежат неукоснительному уничтожению.$B$BПосле боя из каждого убитого дворфа следует выдрать хребет, а тело оставить вонять и разлагаться, – в назидание всем, кто осмелится замахнуться на Орду.$B$BВыдранные хребты, как доказательство своих подвигов, сдавайте Язре Кровавый Рык.',NULL),
(7402,'ruRU','Разыскиваются: ОРКИ!','Ваше задание – убивать орков в Альтеракской долине.$B$BУбейте орка и доставьте зуб орка капралу Норгу Грозовой Вершине в Дун Болдар.','Согласно приказу капрала Норга Грозовой Вершины, все солдаты Грозовой Вершины должны убить как можно больше орков.$B$BВ качестве трофея предъявляйте орочьи зубы.$B$BПеред тем, как вырывать оркам зубы, не забывайте надевать защитные перчатки!',NULL),
